import * as React from "react";
import { cn } from "@/lib/utils";
import { SampleButton } from "@/components/ui/sample-button";

export function Hero({ title, body, action, className }: { title: string; body: string; action: string; className?: string }) {
  return (
    <section data-slot="hero" className={cn("flex flex-col items-center gap-6 bg-background px-6 py-16 text-center text-foreground", className)}>
      <h1 className="max-w-2xl text-4xl font-semibold tracking-tight">{title}</h1>
      <p className="max-w-xl text-lg text-muted-foreground">{body}</p>
      <SampleButton>{action}</SampleButton>
    </section>
  );
}
